<script setup lang="ts">import {ref,watch} from 'vue';import {api} from '../../api';import {locale,t} from '../../locales';import '../../styles/app.scss';const q=ref('');const items=ref<any[]>([]);const loading=ref(false);async function search(){if(!q.value.trim()){items.value=[];return}loading.value=true;try{items.value=await api.news(q.value.trim())}catch{uni.showToast({title:t('搜索失败'),icon:'none'})}finally{loading.value=false}}watch(locale,()=>{if(q.value.trim())search()})</script>
<template><view class="inner-page"><view class="inner-nav"><text class="back" @click="uni.navigateBack()"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg></text><text class="nav-title">{{t('搜索')}}</text></view><view class="inner-main"><view class="search-bar"><text class="search-symbol"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg></text><input v-model="q" focus :placeholder="t('搜索新闻、币种、项目')" @confirm="search"/><text class="search-submit" @click="search">{{t('搜索')}}</text></view><view v-if="!items.length" class="inner-card hot-search"><text class="form-label">{{t('热门搜索')}}</text><view class="inner-tabs"><text class="inner-tab" v-for="x in ['BTC','ETH','ETF','美联储']" :key="x" @click="q=x;search()">{{x==='美联储'?t('美联储'):x}}</text></view></view><view v-for="item in items" :key="item.id" class="list-card" @click="uni.navigateTo({url:'/pages/detail/news?id='+item.id})"><view class="list-icon">▤</view><view class="list-copy"><text class="list-title">{{item.title}}</text><text class="list-meta">{{item.source}} · {{item.time}}</text></view><text class="list-arrow">›</text></view></view></view></template>
<style scoped>.search-bar{display:flex;align-items:center;gap:10rpx;height:88rpx;padding:0 20rpx;border:1rpx solid var(--cf-line);border-radius:44rpx;background:#fff;color:var(--cf-soft)}.search-bar>text:first-child{display:grid;place-items:center;flex:0 0 48rpx;width:48rpx;height:56rpx;font-size:42rpx;line-height:1}.search-bar input{flex:1;min-width:0;height:100%;font-size:28rpx}.search-submit{display:flex;align-items:center;justify-content:center;min-width:76rpx;height:64rpx;color:var(--cf-brand);font-size:25rpx;font-weight:700}.hot-search{margin-top:18rpx}.hot-search .inner-tabs{margin:14rpx 0 0}.inner-nav .back{display:grid;place-items:center;flex:0 0 88rpx;width:88rpx;height:88rpx;margin-left:-18rpx;font-size:58rpx!important;line-height:1}</style>
